import React from 'react';
import Dashboard from './components/Dashboard';
import BackgroundMap from './components/BackgroundMap';

function App() {
  return (
    <>
      <BackgroundMap />
      <div style={{
        position: 'relative',
        zIndex: 1,
        padding: '30px',
        maxWidth: '700px',
        margin: 'auto',
        backgroundColor: 'rgba(255, 255, 255, 0.9)',
        borderRadius: '16px',
        boxShadow: '0 0 16px rgba(0,0,0,0.2)'
      }}>
        <h1 style={{ textAlign: 'center' }}>🌬️ Indoor Air Quality Dashboard</h1>
        <Dashboard />
      </div>
    </>
  );
}

export default App;
